# Script Type: API
# API Method: get_contact_simple

customer = frappe.form_dict.get('cust_name')
if customer:
    # 1. Check if the Customer has a "Primary Contact" set in their own record
    # This is the fastest and most standard way
    primary_contact = frappe.db.get_value("Customer", customer, "customer_primary_contact")

    if primary_contact:
        frappe.response['message'] = frappe.get_doc("Contact", primary_contact)
    else:
        # 2. Fallback: Search the "Dynamic Link" table if no primary is set
        # This fixes the "403 Forbidden" error you saw earlier
        link = frappe.db.get_value("Dynamic Link", 
            {"link_doctype": "Customer", "link_name": customer, "parenttype": "Contact"}, 
            "parent"
        )

        if link:
            frappe.response['message'] = frappe.get_doc("Contact", link)
        else:
            frappe.response['message'] = {}
else:
    frappe.response['message'] = {}

