# SCRIPT TYPE: API
# METHOD NAME: delete_debt_record

try:
    user = frappe.session.user
    name = frappe.form_dict.get("name")

    if not user or user == "Guest":
        frappe.response["message"] = {"ok": 0, "error": "Guest session"}

    elif not name:
        frappe.response["message"] = {"ok": 0, "error": "Missing record name"}

    else:
        doc = frappe.get_doc("LMT Debt Collection", name)

        # Must belong to this sales rep
        if (doc.get("agent_name") or "") != user:
            frappe.response["message"] = {"ok": 0, "error": "Not allowed (record not assigned to you)"}

        else:
            # Permission check
            if not frappe.has_permission("LMT Debt Collection", "delete", doc=doc):
                frappe.response["message"] = {"ok": 0, "error": "No delete permission"}

            else:
                if doc.docstatus == 1:
                    if not frappe.has_permission("LMT Debt Collection", "cancel", doc=doc):
                        frappe.response["message"] = {"ok": 0, "error": "No cancel permission (cannot delete submitted)"}
                    else:
                        doc.cancel()
                        frappe.delete_doc("LMT Debt Collection", name, force=1)
                        frappe.response["message"] = {"ok": 1}

                elif doc.docstatus == 0:
                    frappe.delete_doc("LMT Debt Collection", name, force=1)
                    frappe.response["message"] = {"ok": 1}

                else:
                    frappe.response["message"] = {"ok": 0, "error": "Record is cancelled"}

except Exception as e:
    frappe.log_error(frappe.get_traceback(), "delete_debt_record failed")
    frappe.response["message"] = {"ok": 0, "error": str(e)}

