frappe.response["message"] = {"debts": debts}

# Server Script: lmt_batch_create_v1
# Type: API

action = frappe.form_dict.get("action")

def clean_code(s, max_len=32):
    s = (s or "").strip().upper()
    s = "".join(ch for ch in s if ch.isalnum() or ch in ["-", "_"])
    return s[:max_len] or "ITEM"

def ensure_batch(item_name, expiry_dt):
    existing = frappe.db.get_value("Batch", {"item": item_name, "expiry_date": expiry_dt}, "name")
    if existing:
        return existing
    item_code = frappe.db.get_value("Item", item_name, "item_code") or item_name
    ymd = str(expiry_dt).replace("-", "")[:8]
    batch_id = ymd + "-" + clean_code(item_code)
    if frappe.db.exists("Batch", batch_id):
        batch_id = batch_id + "-" + frappe.generate_hash(length=4).upper()
    b = frappe.get_doc({
        "doctype": "Batch",
        "batch_id": batch_id,
        "item": item_name,
        "expiry_date": expiry_dt
    })
    b.insert(ignore_permissions=True)
    return b.name


if action == "list":
    suppliers = frappe.db.get_all("Supplier",
        filters={"disabled": 0},
        fields=["name", "supplier_name"],
        order_by="supplier_name", limit_page_length=0)
    supplier_groups = frappe.db.get_all("Supplier Group",
        filters={"is_group": 0},
        fields=["name"], order_by="name", limit_page_length=0)
    warehouses = frappe.db.get_all("Warehouse",
        filters={"is_group": 0, "disabled": 0},
        fields=["name"], order_by="name", limit_page_length=0)
    frappe.response["message"] = {
        "suppliers": suppliers,
        "supplier_groups": [g.name for g in supplier_groups],
        "warehouses": [w.name for w in warehouses]
    }


elif action == "search_items":
    q = (frappe.form_dict.get("query") or "").strip()
    if not q:
        frappe.response["message"] = {"items": []}
    else:
        items = frappe.db.sql("""
            SELECT name, item_code, item_name, has_batch_no
            FROM `tabItem`
            WHERE is_purchase_item = 1 AND disabled = 0
              AND (item_code LIKE %(q)s OR item_name LIKE %(q)s)
            ORDER BY item_code
            LIMIT 20
        """, {"q": "%" + q + "%"}, as_dict=True)
        frappe.response["message"] = {"items": items}


elif action == "create_supplier":
    sname = (frappe.form_dict.get("supplier_name") or "").strip()
    sgroup = (frappe.form_dict.get("supplier_group") or "").strip()
    if not sname or not sgroup:
        frappe.response["message"] = {"error": "اسم المورد ومجموعة المورد مطلوبة"}
    else:
        existing = frappe.db.get_value("Supplier", {"supplier_name": sname}, "name")
        if existing:
            frappe.response["message"] = {"name": existing, "supplier_name": sname, "existed": 1}
        else:
            s = frappe.get_doc({
                "doctype": "Supplier",
                "supplier_name": sname,
                "supplier_group": sgroup,
                "supplier_type": "Company",
                "country": "Libya"
            })
            s.insert(ignore_permissions=True)
            frappe.response["message"] = {"name": s.name, "supplier_name": s.supplier_name, "existed": 0}


elif action == "list_pending_orders":
    orders = frappe.db.sql("""
        SELECT name, supplier, supplier_name, transaction_date, status, per_received, grand_total
        FROM `tabPurchase Order`
        WHERE docstatus = 1 
          AND status IN ('To Receive', 'To Receive and Bill')
        ORDER BY transaction_date DESC
        LIMIT 100
    """, as_dict=True)
    frappe.response["message"] = {"orders": orders}


elif action == "get_order_items":
    po_name = (frappe.form_dict.get("po") or "").strip()
    if not po_name:
        frappe.response["message"] = {"error": "اختر أمر شراء"}
    else:
        po = frappe.get_doc("Purchase Order", po_name)
        rows = []
        for it in po.items:
            outstanding = frappe.utils.flt(it.qty) - frappe.utils.flt(it.received_qty)
            if outstanding <= 0:
                continue
            has_batch = int(frappe.db.get_value("Item", it.item_code, "has_batch_no") or 0)
            rows.append({
                "po_detail": it.name,
                "item_code": it.item_code,
                "item_name": it.item_name,
                "qty_ordered": it.qty,
                "qty_received": it.received_qty,
                "qty_outstanding": outstanding,
                "rate": it.rate,
                "has_batch_no": has_batch
            })
        frappe.response["message"] = {
            "po": po.name,
            "supplier": po.supplier,
            "supplier_name": po.supplier_name,
            "items": rows
        }


elif action == "create_receipt":
    supplier = (frappe.form_dict.get("supplier") or "").strip()
    warehouse = (frappe.form_dict.get("warehouse") or "").strip()
    posting_date = (frappe.form_dict.get("posting_date") or "").strip()
    purchase_order = (frappe.form_dict.get("purchase_order") or "").strip()
    items_raw = frappe.form_dict.get("items") or "[]"

    error_msg = None
    if not supplier:
        error_msg = "اختر المورد"
    elif not warehouse:
        error_msg = "اختر المستودع"

    items = []
    parse_err = ""
    if not error_msg:
        if isinstance(items_raw, list):
            items = items_raw
        elif isinstance(items_raw, str):
            try:
                items = json.loads(items_raw)
            except Exception:
                items = []
                parse_err = "json fail"
        if not items:
            error_msg = "[S] لا أصناف — " + parse_err + " raw=" + str(items_raw)[:150]

    pr_doc = None
    created_batches = []
    flipped_items = []
    flipped_stock_items = []

    if not error_msg:
        pr_doc = frappe.new_doc("Purchase Receipt")
        pr_doc.supplier = supplier
        pr_doc.posting_date = posting_date or frappe.utils.nowdate()
        pr_doc.set_warehouse = warehouse
        pr_doc.currency = "LYD"

        for row in items:
            item_code = (row.get("item_code") or "").strip()
            qty = frappe.utils.flt(row.get("qty"))
            rate = frappe.utils.flt(row.get("rate"))
            expiry = row.get("expiry") or None
            po_detail = row.get("po_detail") or None

            if not item_code or qty <= 0:
                error_msg = "كل صنف يحتاج كود وكمية > 0"
                break

            item_name = frappe.db.get_value("Item", {"item_code": item_code}, "name")
            if not item_name:
                error_msg = "صنف غير موجود: " + item_code
                break
            is_stock = int(frappe.db.get_value("Item", item_name, "is_stock_item") or 0)
            if not is_stock:
                frappe.db.set_value("Item", item_name, "is_stock_item", 1)
                flipped_stock_items.append(item_code)

            has_batch = int(frappe.db.get_value("Item", item_name, "has_batch_no") or 0)
            batch_no = ""

            if expiry and not has_batch:
                frappe.db.set_value("Item", item_name, "has_batch_no", 1)
                frappe.db.set_value("Item", item_name, "create_new_batch", 1)
                has_batch = 1
                flipped_items.append(item_code)

            if has_batch:
                if not expiry:
                    error_msg = "الصنف " + item_code + " يتطلب تاريخ انتهاء"
                    break
                expiry_dt = frappe.utils.getdate(expiry)
                today_dt = frappe.utils.getdate(frappe.utils.nowdate())
                if expiry_dt <= today_dt:
                    error_msg = "تاريخ انتهاء غير صالح للصنف " + item_code + ": " + str(expiry_dt) + " — يجب أن يكون في المستقبل"
                    break
                batch_no = ensure_batch(item_name, expiry_dt)
                created_batches.append(batch_no)

            row_data = {
                "item_code": item_code,
                "qty": qty,
                "rate": rate,
                "warehouse": warehouse,
                "batch_no": batch_no
            }
            if purchase_order and po_detail:
                row_data["purchase_order"] = purchase_order
                row_data["purchase_order_item"] = po_detail
            pr_doc.append("items", row_data)

    if error_msg:
        frappe.response["message"] = {"error": error_msg}
    else:
        pr_doc.insert(ignore_permissions=True)
        pr_doc.submit()
        frappe.response["message"] = {
            "name": pr_doc.name,
            "batches": list(set(created_batches)),
            "total": pr_doc.grand_total,
            "supplier": supplier,
            "flipped": flipped_items,
            "flipped_stock": flipped_stock_items,
            "from_po": purchase_order
        }

caller = frappe.session.user
customer = (frappe.form_dict.get("customer") or "").strip()
action = (frappe.form_dict.get("action") or "").strip()
note = (frappe.form_dict.get("note") or "").strip()

role_rows = frappe.db.sql("SELECT role FROM `tabHas Role` WHERE parent=%s AND parenttype='User'", (caller,), as_dict=True)
roles = set(rr.role for rr in role_rows)
is_admin = (caller == "Administrator") or ("System Manager" in roles) or ("lmt_clearance_admin" in roles)
is_supervisor = "lmt_clearance_supervisor" in roles

ok = 1
msg = None

if not (is_admin or is_supervisor):
    msg = {"status": "deny", "message": "ليس لديك صلاحية."}
    ok = 0

if ok and (not customer or action not in ("Approved", "Rejected", "DisableApprove", "DisableReject")):
    msg = {"status": "error", "message": "بيانات ناقصة."}
    ok = 0

cust_mgr = None
if ok:
    cust_mgr = frappe.db.get_value("Customer", customer, "account_manager")
    if not cust_mgr:
        msg = {"status": "error", "message": "الزبون غير موجود."}
        ok = 0

if ok and is_supervisor and not is_admin:
    sup_of = frappe.db.get_value("User", cust_mgr, "lmt_supervisor_user")
    if sup_of != caller and cust_mgr != caller:
        msg = {"status": "deny", "message": "هذا الزبون ليس ضمن نطاقك."}
        ok = 0

if ok and action == "Rejected" and not note:
    msg = {"status": "error", "message": "سبب الرفض مطلوب."}
    ok = 0

if ok:
    if action == "DisableApprove":
        frappe.db.set_value("Customer", customer, {
            "disabled": 1,
            "custom_disable_requested": 0,
            "custom_clearance_by": caller,
            "custom_clearance_on": frappe.utils.now(),
            "custom_clearance_note": note or ("أُوقف بواسطة " + caller)
        })
    elif action == "DisableReject":
        frappe.db.set_value("Customer", customer, {
            "custom_disable_requested": 0,
            "custom_disable_requested_by": "",
            "custom_disable_reason": "",
            "custom_clearance_by": caller,
            "custom_clearance_on": frappe.utils.now(),
            "custom_clearance_note": note or ("رُفض طلب الإيقاف بواسطة " + caller)
        })
    else:
        frappe.db.set_value("Customer", customer, {
            "custom_sales_clearance": action,
            "custom_clearance_by": caller,
            "custom_clearance_on": frappe.utils.now(),
            "custom_clearance_note": note or ("اعتُمد بواسطة " + caller)
        })
    frappe.db.commit()
    msg = {"status": "ok", "customer": customer, "new_status": action}

frappe.response["message"] = msg

# Page Cloner API. Deployed: 2026-07-12 09:07:03
user = frappe.session.user
roles = frappe.db.sql("SELECT role FROM `tabHas Role` WHERE parent=%s", (user,), pluck=True) or []
if "System Manager" not in roles:
    frappe.response["message"] = {"status": "error", "message": "Not Permitted"}
else:
    action = frappe.form_dict.get("action")

    def next_route(name):
        parts = name.rsplit("_", 1)
        if len(parts) == 2 and parts[1].isdigit():
            return parts[0] + "_" + str(int(parts[1]) + 1)
        return name + "_1"

    def next_api(name):
        parts = name.rsplit("_", 1)
        if len(parts) == 2 and parts[1].isdigit():
            return parts[0] + "_" + str(int(parts[1]) + 1)
        if len(parts) == 2 and parts[1].startswith("v") and parts[1][1:].isdigit():
            return parts[0] + "_v" + str(int(parts[1][1:]) + 1)
        return name + "_v2"

    def whole_hit(name, blob):
        word = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-."
        pos = blob.find(name)
        while pos != -1:
            before = blob[pos - 1] if pos > 0 else ""
            after_i = pos + len(name)
            after = blob[after_i] if after_i < len(blob) else ""
            if before not in word and after not in word:
                return True
            pos = blob.find(name, pos + 1)
        return False

    def find_apis(js):
        found = set()
        names = frappe.get_all("Server Script", pluck="name")
        for nm in names:
            if nm and len(nm) >= 3 and whole_hit(nm, js):
                found.add(nm)
        return found

    def find_pfs(js, html):
        found = set()
        blob = (js or "") + chr(10) + (html or "")
        names = frappe.get_all("Print Format", pluck="name")
        for nm in names:
            if nm and len(nm) >= 4 and whole_hit(nm, blob):
                found.add(nm)
        return found

    if action == "list":
        pages = frappe.db.sql("""SELECT route, title FROM `tabWeb Page`
            WHERE published = 1 ORDER BY route""", as_dict=True)
        frappe.response["message"] = {"status": "success", "data": pages}

    elif action == "clone":
        src_route = frappe.form_dict.get("source_route")
        update_menu = frappe.form_dict.get("update_menu") in ("1", 1, "true", True)
        log = []
        try:
            src_name = frappe.db.get_value("Web Page", {"route": src_route}, "name")
            if not src_name:
                frappe.throw("Source route not found: " + str(src_route))
            new_route = next_route(src_route)
            src = frappe.get_doc("Web Page", src_name)
            html_c = src.main_section_html or src.main_section or ""
            css_c = src.css or ""
            js_c = src.javascript or ""

            rename = {}
            for old_api in sorted(find_apis(js_c)):
                new_api_name = next_api(old_api)
                rename[old_api] = new_api_name
                old_code = frappe.db.get_value("Server Script", old_api, "script") or ""
                new_code = "# Cloned from " + old_api + "\n" + old_code
                if not frappe.db.exists("Server Script", new_api_name):
                    ss = frappe.new_doc("Server Script")
                    ss.name = new_api_name
                    ss.script_type = "API"
                    ss.api_method = new_api_name
                    ss.allow_guest = frappe.db.get_value("Server Script", old_api, "allow_guest") or 0
                    ss.script = new_code
                    ss.insert(ignore_permissions=True)
                else:
                    frappe.db.set_value("Server Script", new_api_name, "script", new_code)
                log.append("API: " + old_api + " -> " + new_api_name)

            for old_api in sorted(rename, key=len, reverse=True):
                js_c = js_c.replace(old_api, rename[old_api])

            tgt = frappe.db.get_value("Web Page", {"route": new_route}, "name")
            if not tgt:
                wp = frappe.new_doc("Web Page")
                wp.title = new_route
                wp.route = new_route
                wp.published = 1
                wp.content_type = "HTML"
                wp.main_section = html_c
                wp.insert(ignore_permissions=True)
                tgt = wp.name
            frappe.db.set_value("Web Page", tgt, {
                "main_section": html_c, "main_section_html": html_c,
                "css": css_c, "javascript": js_c, "insert_style": 1,
                "content_type": "HTML", "published": 1}, update_modified=True)
            log.append("Page: " + src_route + " -> " + new_route)

            if update_menu:
                menus = frappe.get_all("LMT Mobile Menu Item", filters={"route": src_route})
                for mn in menus:
                    frappe.db.set_value("LMT Mobile Menu Item", mn.name, "route", new_route)
                log.append("Menu repointed: " + str(len(menus)) + " item(s)")
            else:
                log.append("Menu unchanged - test first, flip later")

            frappe.response["message"] = {"status": "success", "new_route": new_route, "log": log}
        except Exception as e:
            frappe.log_error("Page Cloner Error: " + str(e))
            frappe.response["message"] = {"status": "error", "message": str(e), "log": log}

    elif action == "dump":
        src_route = frappe.form_dict.get("source_route")
        try:
            src_name = frappe.db.get_value("Web Page", {"route": src_route}, "name")
            if not src_name:
                frappe.throw("Source route not found: " + str(src_route))
            src = frappe.get_doc("Web Page", src_name)
            html_c = src.main_section_html or src.main_section or ""
            css_c = src.css or ""
            js_c = src.javascript or ""

            parts = []
            parts.append("# Web Page Dump: " + src_route)
            parts.append("Generated: " + frappe.utils.now())
            parts.append("")
            parts.append("## HTML (main_section)")
            parts.append("```html")
            parts.append(html_c)
            parts.append("```")
            parts.append("")
            parts.append("## CSS")
            parts.append("```css")
            parts.append(css_c)
            parts.append("```")
            parts.append("")
            parts.append("## JavaScript")
            parts.append("```javascript")
            parts.append(js_c)
            parts.append("```")

            apis = sorted(find_apis(js_c))
            api_blob = ""
            for api in apis:
                meta = frappe.db.get_value("Server Script", api,
                    ["script", "script_type", "api_method", "allow_guest", "disabled"], as_dict=True) or {}
                parts.append("")
                parts.append("## API Server Script: " + api)
                parts.append("- script_type: " + str(meta.get("script_type") or ""))
                parts.append("- api_method: " + str(meta.get("api_method") or ""))
                parts.append("- allow_guest: " + str(meta.get("allow_guest") or 0))
                parts.append("- disabled: " + str(meta.get("disabled") or 0))
                parts.append("")
                parts.append("```python")
                parts.append(meta.get("script") or "")
                parts.append("```")
                api_blob = api_blob + chr(10) + (meta.get("script") or "")
            if not apis:
                parts.append("")
                parts.append("## API Server Script: (none detected)")

            pfs = sorted(find_pfs(js_c, html_c))
            for pf in pfs:
                pfd = frappe.db.get_value("Print Format", pf,
                    ["doc_type", "module", "print_format_type", "standard",
                     "custom_format", "disabled", "html", "css", "format_data"],
                    as_dict=True) or {}
                parts.append("")
                parts.append("## Print Format: " + pf)
                parts.append("- doc_type: " + str(pfd.get("doc_type") or ""))
                parts.append("- module: " + str(pfd.get("module") or ""))
                parts.append("- print_format_type: " + str(pfd.get("print_format_type") or ""))
                parts.append("- standard: " + str(pfd.get("standard") or ""))
                parts.append("- custom_format: " + str(pfd.get("custom_format") or 0))
                parts.append("- disabled: " + str(pfd.get("disabled") or 0))
                parts.append("")
                parts.append("### Print Format HTML")
