/* ===== LMT export kit (generic) — reads the table on screen, works with current filters ===== */
const LMT_PF = "LMT Generic Table Report";
const LMT_DT = "LMT Export Payload";
const LMT_TITLE = ((document.querySelector('.sr-title') || {}).textContent || 'تقرير').trim();
function lmtFileName(ext){ return LMT_TITLE.split(' ').join('_') + '_' + frappe.datetime.now_date() + ext; }
function lmtCollectTable(){
  const t = document.querySelector('#srTable') || document.querySelector('table');
  if(!t) return null;
  const cols = [...t.querySelectorAll('thead th')].map(th => th.textContent.trim());
  const rows = [...t.querySelectorAll('tbody tr')]
    .filter(tr => !tr.querySelector('.empty, .loading-row') && tr.querySelectorAll('td').length > 1)
    .map(tr => [...tr.querySelectorAll('td')].map(td => td.textContent.trim()));
  return { cols: cols, rows: rows };
}
function lmtLoadScript(s1, cb){
  const s = document.createElement('script'); s.src = s1; s.onload = cb;
  s.onerror = () => frappe.msgprint('تعذر تحميل المكتبة'); document.head.appendChild(s);
}
function lmtExportXLSX(data){
  const d = data || lmtCollectTable();
  if(!d || !d.rows.length){ frappe.msgprint('لا توجد بيانات للتصدير'); return; }
  const go = () => {
    const aoa = [d.cols].concat(d.rows.map(r => r.map(v => {
      const n = Number(String(v).split(',').join(''));
      return (v !== '' && !isNaN(n)) ? n : v;
    })));
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = d.cols.map(() => ({ wch: 18 }));
    ws['!freeze'] = { xSplit: 0, ySplit: 1 };
    ws['!autofilter'] = { ref: XLSX.utils.encode_range({ s:{r:0,c:0}, e:{r:d.rows.length, c:d.cols.length-1} }) };
    const wb = XLSX.utils.book_new();
    wb.Workbook = { Views: [{ RTL: true }] };
    XLSX.utils.book_append_sheet(wb, ws, 'Report');
    XLSX.writeFile(wb, lmtFileName('.xlsx'));
  };
  window.XLSX ? go() : lmtLoadScript('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js', go);
}
function lmtExportPDF(data, meta, summary){
  const d = data || lmtCollectTable();
  if(!d || !d.rows.length){ frappe.msgprint('لا توجد بيانات للتصدير'); return; }
  frappe.call({
    method: 'lmt_export_payload_v1',
    args: { action: 'save', title: LMT_TITLE,
            payload: JSON.stringify({ title: LMT_TITLE, columns: d.cols, rows: d.rows, meta: meta || [], summary: summary || [] }) },
    freeze: true, freeze_message: 'جاري تجهيز الملف...',
    callback: (r) => {
      const m = r.message || {};
      if(m.status !== 'ok'){ frappe.msgprint('فشل التصدير'); return; }
      const p = new URLSearchParams();
      p.set('doctype', LMT_DT); p.set('name', m.name); p.set('format', LMT_PF);
      p.set('no_letterhead', '1'); p.set('_lang', 'ar');
      const a = document.createElement('a');
      a.href = '/api/method/frappe.utils.print_format.download_pdf?' + p.toString();
      a.download = lmtFileName('.pdf');
      document.body.appendChild(a); a.click(); a.remove();
    }
  });
}
