    "SUM(CASE WHEN is_return=1 THEN ABS(grand_total) ELSE 0 END) as ret "
    "FROM `tabSales Invoice` WHERE customer IN %s AND docstatus=1 GROUP BY customer",
    (customer_ids,), as_dict=True):
    erp_sales_all_map[row.customer] = float(row.sales or 0)
    erp_ret_all_map[row.customer] = float(row.ret or 0)
for row in frappe.db.sql(
    "SELECT customer, "
    "SUM(CASE WHEN is_return=0 THEN grand_total ELSE 0 END) as sales, "
    "SUM(CASE WHEN is_return=1 THEN ABS(grand_total) ELSE 0 END) as ret "
    "FROM `tabSales Invoice` WHERE customer IN %s AND docstatus=1 AND posting_date>=%s AND posting_date<=%s GROUP BY customer",
    (customer_ids, range_start, range_end), as_dict=True):
    erp_sales_range_map[row.customer] = float(row.sales or 0)
    erp_ret_range_map[row.customer] = float(row.ret or 0)

# ── ERPNext Payment Entry all-time ──
erp_pe_all_map = {}
for row in frappe.db.sql(
    "SELECT party, SUM(paid_amount) as total FROM `tabPayment Entry` "
    "WHERE party_type='Customer' AND party IN %s AND docstatus=1 AND payment_type='Receive' "
    "GROUP BY party", (customer_ids,), as_dict=True):
    erp_pe_all_map[row.party] = float(row.total or 0)

# ── ERPNext JE credits all-time ──
erp_je_all_map = {}
for row in frappe.db.sql(
    "SELECT jea.party, SUM(jea.credit_in_account_currency) as total "
    "FROM `tabJournal Entry Account` jea JOIN `tabJournal Entry` je ON je.name=jea.parent "
    "WHERE jea.party_type='Customer' AND jea.party IN %s AND je.docstatus=1 "
    "AND COALESCE(je.is_opening,'No')='No' AND jea.credit_in_account_currency > 0 "
    "GROUP BY jea.party", (customer_ids,), as_dict=True):
    erp_je_all_map[row.party] = float(row.total or 0)

# ── ERPNext last dates ──
erp_last_sale_map = {}
erp_last_recv_map = {}
for row in frappe.db.sql(
    "SELECT customer, MAX(posting_date) as d FROM `tabSales Invoice` "
    "WHERE customer IN %s AND docstatus=1 AND is_return=0 GROUP BY customer",
    (customer_ids,), as_dict=True):
    erp_last_sale_map[row.customer] = row.d
for row in frappe.db.sql(
    "SELECT party, MAX(posting_date) as d FROM `tabPayment Entry` "
    "WHERE party_type='Customer' AND party IN %s AND docstatus=1 GROUP BY party",
    (customer_ids,), as_dict=True):
    erp_last_recv_map[row.party] = row.d

# ── Per customer ──
result = {}
for cid in customer_ids:
    cd = cust_data.get(cid, {"lmt_key": "", "cust_class": "C", "collect_exception": 0, "creation": None})
    lk = cd["lmt_key"]
    cclass = cd["cust_class"] or "C"
    clr = cd.get("clearance") or "Pending"

    if clr == "Rejected":
        result[cid] = {"blocked": True, "reason": "clearance_rejected", "percentage": 0, "balance": 0, "message": "الزبون مرفوض من الإدارة. لا يمكن البيع. اتصل بالمشرف."}
        continue
    if clr != "Approved":
        result[cid] = {"blocked": True, "reason": "clearance_pending", "percentage": 0, "balance": 0, "message": "الزبون بانتظار اعتماد المشرف. لا يمكن البيع حتى الاعتماد."}
        continue

    if cd.get("collect_exception"):
        result[cid] = {"blocked": False, "reason": "collect_exception", "percentage": 0, "balance": 0}
        continue

    rule = rules_map.get(cclass)
    if not rule:
        result[cid] = {"blocked": False, "reason": "no_rule", "percentage": 0, "balance": 0}
        continue

    MAX_BAL = float(rule.max_balance or 50)
    MAX_RATIO = float(rule.max_debt_ratio or 30) / 100.0
    D_SALE = int(rule.days_since_sale or 30)
    D_RECV = int(rule.days_since_receive or 45)
    LOGIC = (rule.logic_equation or "BALANCE AND RATIO").strip().upper()

    if not lk and cd["creation"]:
        cr = cd["creation"]
        try:
            cr = cr.date()
        except AttributeError:
            pass
        if frappe.utils.date_diff(today, cr) <= NEW_CUSTOMER_GRACE_DAYS:
            result[cid] = {"blocked": False, "reason": "new_customer", "percentage": 0, "balance": 0}
            continue

    ts_all = lmt_sales_all_map.get(lk, 0) + erp_sales_all_map.get(cid, 0) - erp_ret_all_map.get(cid, 0)
    tr_all = lmt_recv_all_map.get(lk, 0) + erp_pe_all_map.get(cid, 0) + erp_je_all_map.get(cid, 0)
    balance_val = tr_all - ts_all
    ts_range = lmt_sales_range_map.get(lk, 0) + erp_sales_range_map.get(cid, 0) - erp_ret_range_map.get(cid, 0)

    if ts_all == 0:
        ratio_val = -1.0 if balance_val < 0 else 0.0
    elif ts_range == 0:
        ratio_val = -1.0 if balance_val < 0 else 0.0
    elif ts_range >= ts_all:
        ratio_val = balance_val / ts_all
    else:
        pf = balance_val / ts_all
        pr = balance_val / ts_range
        ratio_val = pr if pr < pf else pf

    ds = [d for d in [lmt_last_sale_map.get(lk), erp_last_sale_map.get(cid)] if d]
    dr = [d for d in [lmt_last_recv_map.get(lk), erp_last_recv_map.get(cid)] if d]
    last_sale = max(ds) if ds else None
    last_recv = max(dr) if dr else None
    days_sale = frappe.utils.date_diff(today, last_sale) if last_sale else 9999
    days_recv = frappe.utils.date_diff(today, last_recv) if last_recv else 9999

    has_history = (ts_all > 0 or tr_all > 0 or lk)
    if not has_history:
        result[cid] = {"blocked": False, "reason": "no_history", "percentage": 0, "balance": 0}
        continue

    vb = (balance_val < 0) and (abs(balance_val) > MAX_BAL)
    vr = (balance_val < 0) and (abs(ratio_val) > MAX_RATIO)
    vds = days_sale > D_SALE
    vdr = days_recv > D_RECV

    expr = LOGIC
    expr = expr.replace("DAYS_RECV", "T" if vdr else "F")
    expr = expr.replace("DAYS_SALE", "T" if vds else "F")
    expr = expr.replace("BALANCE", "T" if vb else "F")
    expr = expr.replace("RATIO", "T" if vr else "F")

    blocked = False
    or_parts = expr.split(" OR ")
    for op in or_parts:
        and_parts = op.strip().split(" AND ")
        and_ok = True
        for ap in and_parts:
            val = ap.strip().replace("(", "").replace(")", "")
            if val == "F":
                and_ok = False
            elif val.startswith("NOT "):
                if val[4:].strip() == "T":
                    and_ok = False
        if and_ok:
            blocked = True
            break

    if blocked:
        pct_d = round(abs(ratio_val) * 100, 1)
        debt = round(abs(balance_val), 3)
        max_p = round(MAX_RATIO * 100, 1)
        ar = []
        if vr:
            ar.append("نسبة الديون " + str(pct_d) + "% تتجاوز الحد المسموح (" + str(max_p) + "%)")
        if vdr:
            ar.append("لم يسدد منذ " + str(days_recv) + " يوم")
        denom = ts_range if (ts_range > 0 and ts_range < ts_all) else ts_all
        if denom > 0 and vr:
            target_balance = MAX_RATIO * denom
            pay_needed = round(abs(balance_val) - target_balance, 3)
            if pay_needed < 0:
                pay_needed = 0
        else:
            pay_needed = round(abs(balance_val) - MAX_BAL, 3)
            if pay_needed < 0:
                pay_needed = 0

        cdisp = frappe.db.get_value("Customer", cid, "customer_name") or cid
        msg = "الزبون (" + str(cdisp) + ") محظور: " + " و ".join(ar) + ". الرصيد = " + str(debt) + " د.ل."
        msg = msg + " يحتاج لدفع " + str(round(pay_needed, 3)) + " د.ل على الأقل لفك الحظر."
        msg = msg + " اتصل بمسؤولك المباشر."
        result[cid] = {"blocked": True, "percentage": round(ratio_val * 100, 1), "balance": round(balance_val, 3), "payment_to_unblock": pay_needed, "message": msg}
    else:
        result[cid] = {"blocked": False, "reason": "OK", "percentage": round(ratio_val * 100, 1), "balance": round(balance_val, 3)}

frappe.response["message"] = result

