    br = frappe.db.sql("SELECT max_balance, max_debt_ratio FROM `tabLMT Block Rule` WHERE is_active=1 LIMIT 1", as_dict=True)
    BMAX = 50.0
    BRATIO = 0.30
    if br:
        BMAX = float(br[0]["max_balance"] or 50)
        BRATIO = float(br[0]["max_debt_ratio"] or 30) / 100.0
    mstart = tds[0:7] + "-01"
    if mparam:
        mstart = mparam + "-01"
    mnext = frappe.utils.add_months(frappe.utils.getdate(mstart), 1)
    kmode = frappe.form_dict.get("mode") or "ytd"
    if kmode == "month":
        w_start = mstart
        w_end = frappe.utils.add_days(mnext, -1)
        if frappe.utils.getdate(w_end) > today:
            w_end = tds
        pace = (frappe.utils.date_diff(w_end, w_start) + 1.0) / (frappe.utils.date_diff(frappe.utils.add_days(mnext, -1), mstart) + 1.0)
        tdiv = 12.0
    else:
        w_start = y0
        w_end = tds
        pace = elapsed
        tdiv = 1.0
    if pace <= 0:
        pace = 1.0

    custs = frappe.db.sql("SELECT name, IFNULL(custom_txt_1,%s) ck, IFNULL(account_manager,%s) am FROM `tabCustomer` WHERE IFNULL(disabled,0)=0 AND IFNULL(account_manager,%s) != %s AND IFNULL(custom_collect_exception,0)=0 AND IFNULL(custom_is_distressed,0)=0", ("", "", "", ""), as_dict=True)
    cids = []
    keys = []
    for c in custs:
        cids.append(c["name"])
        if c["ck"]:
            keys.append(c["ck"])

    lsa = {}
    lsw = {}
    lso = {}
    lsn = {}
    lra = {}
    lro = {}
    lrn = {}
    if keys:
        for rr in frappe.db.sql("SELECT customer_key ck, COALESCE(SUM(total_cost),0) a, COALESCE(SUM(CASE WHEN order_date >= %s THEN total_cost ELSE 0 END),0) w, COALESCE(SUM(CASE WHEN order_date <= %s THEN total_cost ELSE 0 END),0) o, COALESCE(SUM(CASE WHEN order_date >= %s THEN total_cost ELSE 0 END),0) n FROM `tabLMT Order` WHERE customer_key IN %s AND order_status=%s GROUP BY customer_key", (WIN, BASE, ystart, keys, "Complete"), as_dict=True):
            lsa[rr["ck"]] = float(rr["a"] or 0)
            lsw[rr["ck"]] = float(rr["w"] or 0)
            lso[rr["ck"]] = float(rr["o"] or 0)
            lsn[rr["ck"]] = float(rr["n"] or 0)
        for rr in frappe.db.sql("SELECT customer_key ck, COALESCE(SUM(received + IFNULL(custom_settlement_discount,0)),0) a, COALESCE(SUM(CASE WHEN date <= %s THEN received + IFNULL(custom_settlement_discount,0) ELSE 0 END),0) o, COALESCE(SUM(CASE WHEN date >= %s THEN received + IFNULL(custom_settlement_discount,0) ELSE 0 END),0) n FROM `tabLMT Payment` WHERE customer_key IN %s GROUP BY customer_key", (BASE, ystart, keys), as_dict=True):
            lra[rr["ck"]] = float(rr["a"] or 0)
            lro[rr["ck"]] = float(rr["o"] or 0)
            lrn[rr["ck"]] = float(rr["n"] or 0)

    esa = {}
    esw = {}
    eso = {}
    esn = {}
    era = {}
    ero = {}
    ern = {}
    eja = {}
    ejo = {}
    ejn = {}
    touched = {}
    if cids:
        for rr in frappe.db.sql("SELECT customer, COALESCE(SUM(CASE WHEN is_return=0 THEN grand_total ELSE -ABS(grand_total) END),0) a, COALESCE(SUM(CASE WHEN posting_date >= %s THEN (CASE WHEN is_return=0 THEN grand_total ELSE -ABS(grand_total) END) ELSE 0 END),0) w, COALESCE(SUM(CASE WHEN posting_date <= %s THEN (CASE WHEN is_return=0 THEN grand_total ELSE -ABS(grand_total) END) ELSE 0 END),0) o, COALESCE(SUM(CASE WHEN posting_date >= %s THEN (CASE WHEN is_return=0 THEN grand_total ELSE -ABS(grand_total) END) ELSE 0 END),0) n FROM `tabSales Invoice` WHERE customer IN %s AND docstatus=1 GROUP BY customer", (WIN, BASE, ystart, cids), as_dict=True):
            esa[rr["customer"]] = float(rr["a"] or 0)
            esw[rr["customer"]] = float(rr["w"] or 0)
            eso[rr["customer"]] = float(rr["o"] or 0)
            esn[rr["customer"]] = float(rr["n"] or 0)
        for rr in frappe.db.sql("SELECT party, COALESCE(SUM(paid_amount),0) a, COALESCE(SUM(CASE WHEN posting_date <= %s THEN paid_amount ELSE 0 END),0) o, COALESCE(SUM(CASE WHEN posting_date >= %s THEN paid_amount ELSE 0 END),0) n FROM `tabPayment Entry` WHERE party_type=%s AND party IN %s AND docstatus=1 AND payment_type=%s GROUP BY party", (BASE, ystart, "Customer", cids, "Receive"), as_dict=True):
            era[rr["party"]] = float(rr["a"] or 0)
            ero[rr["party"]] = float(rr["o"] or 0)
            ern[rr["party"]] = float(rr["n"] or 0)
        for rr in frappe.db.sql("SELECT jea.party p, COALESCE(SUM(jea.credit_in_account_currency),0) a, COALESCE(SUM(CASE WHEN je.posting_date <= %s THEN jea.credit_in_account_currency ELSE 0 END),0) o, COALESCE(SUM(CASE WHEN je.posting_date >= %s THEN jea.credit_in_account_currency ELSE 0 END),0) n FROM `tabJournal Entry Account` jea JOIN `tabJournal Entry` je ON je.name=jea.parent WHERE jea.party_type=%s AND jea.party IN %s AND je.docstatus=1 AND COALESCE(je.is_opening,%s)=%s AND jea.credit_in_account_currency > 0 GROUP BY jea.party", (BASE, ystart, "Customer", cids, "No", "No"), as_dict=True):
            eja[rr["p"]] = float(rr["a"] or 0)
            ejo[rr["p"]] = float(rr["o"] or 0)
            ejn[rr["p"]] = float(rr["n"] or 0)
        for rr in frappe.db.sql("SELECT c.account_manager am, COUNT(DISTINCT c.name) n FROM `tabCustomer` c WHERE c.name IN %s AND ( EXISTS (SELECT 1 FROM `tabSales Order` so WHERE so.customer=c.name AND so.docstatus=1 AND so.transaction_date>=%s AND so.transaction_date<%s) OR EXISTS (SELECT 1 FROM `tabLMT Debt Collection` dc WHERE dc.customer=c.name AND dc.docstatus=1 AND dc.posting_date>=%s AND dc.posting_date<%s) OR EXISTS (SELECT 1 FROM `tabPayment Entry` pe WHERE pe.party=c.name AND pe.party_type=%s AND pe.docstatus=1 AND pe.posting_date>=%s AND pe.posting_date<%s) ) GROUP BY c.account_manager", (cids, mstart, mnext, mstart, mnext, "Customer", mstart, mnext), as_dict=True):
            touched[rr["am"]] = int(rr["n"] or 0)

    ag_debt = {}
    ag_sales = {}
    ag_coll = {}
    ag_blk = {}
    ag_n = {}
    for c in custs:
        a = c["am"]
        lk = c["ck"]
        ts_all = lsa.get(lk, 0) + esa.get(c["name"], 0)
        ts_win = lsw.get(lk, 0) + esw.get(c["name"], 0)
        tr_all = lra.get(lk, 0) + era.get(c["name"], 0) + eja.get(c["name"], 0)
        bal = tr_all - ts_all
        if ts_all == 0 or ts_win == 0:
            cr = 0.0
            if bal < 0:
                cr = -1.0
        elif ts_win >= ts_all:
            cr = bal / ts_all
        else:
            q1 = bal / ts_all
            q2 = bal / ts_win
            cr = q1
            if q2 < q1:
                cr = q2
        owed = (lso.get(lk, 0) + eso.get(c["name"], 0)) - (lro.get(lk, 0) + ero.get(c["name"], 0) + ejo.get(c["name"], 0))
        if owed < 0:
            owed = 0.0
        ag_debt[a] = ag_debt.get(a, 0.0) + owed
        ag_sales[a] = ag_sales.get(a, 0.0) + lsn.get(lk, 0) + esn.get(c["name"], 0)
        ag_coll[a] = ag_coll.get(a, 0.0) + lrn.get(lk, 0) + ern.get(c["name"], 0) + ejn.get(c["name"], 0)
        ag_n[a] = ag_n.get(a, 0) + 1
        if bal < 0 and abs(bal) > BMAX and abs(cr) > BRATIO:
            ag_blk[a] = ag_blk.get(a, 0) + 1

    spec = {}
    for r in frappe.db.sql("SELECT item_group, custom_specialty sp FROM `tabItem` WHERE IFNULL(custom_specialty,%s) <> %s", ("", ""), as_dict=True):
        spec[r["item_group"]] = r["sp"]

    tmap = {}
    for r in frappe.db.sql("SELECT parent p, item_group ig, SUM(target_amount) a FROM `tabTarget Detail` WHERE parenttype=%s AND fiscal_year=%s GROUP BY parent, item_group", ("Sales Person", FY), as_dict=True):
        if r["p"] not in tmap:
            tmap[r["p"]] = {}
        tmap[r["p"]][r["ig"]] = float(r["a"] or 0)
    amap = {}
    for r in frappe.db.sql("SELECT st.sales_person p, sii.item_group ig, SUM(sii.amount) a FROM `tabSales Invoice Item` sii JOIN `tabSales Invoice` si ON si.name=sii.parent JOIN `tabSales Team` st ON st.parent=si.name AND st.parenttype=%s WHERE si.docstatus=1 AND si.posting_date BETWEEN %s AND %s GROUP BY st.sales_person, sii.item_group", ("Sales Invoice", w_start, w_end), as_dict=True):
        if r["p"] not in amap:
            amap[r["p"]] = {}
        amap[r["p"]][r["ig"]] = float(r["a"] or 0)
    lmap = {}
    for r in frappe.db.sql("SELECT o.agent_email e, SUM(oi.total) a FROM `tabLMT Order Item` oi JOIN `tabLMT Order` o ON o.lmt_order_id=oi.order_id WHERE oi.order_status!=%s AND oi.free=0 AND oi.order_date BETWEEN %s AND %s GROUP BY o.agent_email", ("Canceled", w_start, w_end), as_dict=True):
        lmap[r["e"]] = float(r["a"] or 0)
    evmap = {}
    for r in frappe.db.sql("SELECT employee e, AVG(soft_score_pct) a FROM `tabLMT Rep Evaluation` WHERE docstatus=1 GROUP BY employee", as_dict=True):
        evmap[r["e"]] = float(r["a"] or 0)

    emps = frappe.db.sql("SELECT e.name emp, e.employee_name, e.user_id, sp.name spn, IFNULL(e.custom_is_medical_rep,0) med, IFNULL(u.warehouse,%s) wh FROM `tabEmployee` e LEFT JOIN `tabSales Person` sp ON sp.employee = e.name AND sp.enabled = 1 LEFT JOIN `tabUser` u ON u.name = e.user_id WHERE e.status=%s AND IFNULL(e.custom_kpi_exclude,0)=0 AND IFNULL(e.custom_is_sales_agent,0)=1 ORDER BY e.employee_name", ("(غير محدد)", "Active"), as_dict=True)
    groupby = frappe.form_dict.get("groupby") or "agent"

    team = []
    for r in frappe.db.sql("SELECT e.user_id uid FROM `tabEmployee` e LEFT JOIN `tabUser` u ON u.name = e.user_id WHERE e.status=%s AND ( u.lmt_supervisor_user = %s OR ( (u.lmt_supervisor_user IS NULL OR u.lmt_supervisor_user = %s OR u.lmt_supervisor_user = %s) AND e.reports_to IN (SELECT name FROM `tabEmployee` WHERE user_id = %s) ) )", ("Active", me, "", "Administrator", me), as_dict=True):
        if r["uid"]:
            team.append(r["uid"])

    W = [25, 25, 15, 10, 15, 10]
    out = []
    for e in emps:
        em = e["user_id"] or ""
        if not is_admin:
            if em != me and em not in team:
                continue
        spn = e["spn"]
        tgt = 0.0
        ach = 0.0
        tg = tmap.get(spn, {})
        ac = amap.get(spn, {})
        for ig in tg:
            tgt = tgt + tg[ig]
        for ig in ac:
            ach = ach + ac[ig]
        ach = ach + lmap.get(em, 0.0)
        p1 = None
        tgt_w = tgt / tdiv
        if tgt_w > 0:
            p1 = round(100.0 * ach / tgt_w / pace, 1)
        nc = ag_n.get(em, 0)
        denom = (PF * ag_debt.get(em, 0.0) / 12.0 * months) + (CF * ag_sales.get(em, 0.0))
        p2 = None
        if denom > 0:
            p2 = round(100.0 * ag_coll.get(em, 0.0) / denom, 1)
        p3 = None
        p4 = None
        if nc > 0:
            p3 = round(100.0 - (100.0 * ag_blk.get(em, 0) / nc), 1)
            p4 = round(100.0 * touched.get(em, 0) / nc, 1)
        p5 = None
        bys = {}
        for ig in tg:
            s = spec.get(ig, "(unmapped)")
            if s not in bys:
                bys[s] = [0.0, 0.0]
            bys[s][0] = bys[s][0] + tg[ig]
            bys[s][1] = bys[s][1] + ac.get(ig, 0.0)
        itm = {}
        for ig in tg:
            s2 = spec.get(ig, "(unmapped)")
            if s2 not in itm:
                itm[s2] = []
            iv = 0.0
            tgi = tg[ig] / tdiv
            if tgi > 0:
                iv = 100.0 * ac.get(ig, 0.0) / tgi / pace
                if iv > 999:
                    iv = 999.0
            nmi = ig
            if nmi[0:6] == "group-":
                nmi = nmi[6:]
            itm[s2].append({"item": nmi, "tgt": round(tg[ig] / tdiv, 0), "ach": round(ac.get(ig, 0.0), 0), "pct": round(iv, 1)})
        acc = 0.0
        nsp = 0
        det = []
        for s in bys:
            if bys[s][0] > 0:
                v = 100.0 * (bys[s][1] * tdiv) / bys[s][0] / pace
                if v > 120:
                    v = 120.0
                acc = acc + v
                nsp = nsp + 1
                rows_i = itm.get(s, [])
                rows_i.sort(key=lambda z: z["pct"])
                det.append({"sp": s, "tgt": round(bys[s][0] / tdiv, 0), "ach": round(bys[s][1], 0), "pct": round(v, 1), "items": rows_i})
        if nsp:
            p5 = round(acc / nsp, 1)
        det.sort(key=lambda z: z["pct"])
        p6 = None
        if e["emp"] in evmap:
            p6 = round(evmap[e["emp"]], 1)
        vals = [p1, p2, p3, p4, p5, p6]
        num = 0.0
        den = 0.0
        cnt = 0
        i = 0
        for v in vals:
            if v is not None:
                cap = v
                if cap > 120:
                    cap = 120.0
                num = num + cap * W[i]
                den = den + W[i]
                cnt = cnt + 1
            i = i + 1
        comp = None
        if den > 0 and cnt >= 4:
            comp = round(num / den, 1)
        arn = (e["wh"] or "(غير محدد)")
        if arn[-2:] == " S":
            arn = arn[0:-2]
        if arn[-2:] == "- ":
            arn = arn[0:-2]
        arn = arn.strip()
        if arn[-1:] == "-":
            arn = arn[0:-1].strip()
        out.append({"emp": e["emp"], "name": e["employee_name"], "area": arn, "email": em, "med": e["med"], "customers": nc, "p1": p1, "p2": p2, "p3": p3, "p4": p4, "p5": p5, "p6": p6, "comp": comp, "npillar": cnt, "target": round(tgt / tdiv, 0), "achieved": round(ach, 0), "focus_detail": det, "zt": tgt / tdiv, "za": ach, "zpd": ag_debt.get(em, 0.0), "zcs": ag_sales.get(em, 0.0), "zcc": ag_coll.get(em, 0.0), "znc": nc, "zblk": ag_blk.get(em, 0), "ztch": touched.get(em, 0), "zfd": det, "zp6": p6})

    if groupby == "medrep":
        WM = [45, 35, 20]
        mreps = frappe.db.sql("SELECT e.name emp, e.employee_name nm, u.warehouse wh FROM `tabEmployee` e LEFT JOIN `tabUser` u ON u.name = e.user_id WHERE e.status=%s AND IFNULL(e.custom_is_medical_rep,0)=1 AND IFNULL(e.custom_kpi_exclude,0)=0 ORDER BY e.employee_name", ("Active",), as_dict=True)
        mout = []
        for mr in mreps:
            asg = frappe.db.sql("SELECT sales_person spn, specialty sp, IFNULL(allocation_pct,100) al FROM `tabLMT Rep Assignment` WHERE parent=%s AND IFNULL(is_active,1)=1 ORDER BY idx", (mr["emp"],), as_dict=True)
            tree = {}
            for ar in asg:
                spn = ar["spn"]
                wgt = float(ar["al"] or 100) / 100.0
                tg2 = tmap.get(spn, {})
                ac2 = amap.get(spn, {})
                for ig in tg2:
                    sname = spec.get(ig, "(غير مصنف)")
                    if ar["sp"] and sname != ar["sp"]:
                        continue
                    tv = tg2[ig] / tdiv * wgt
                    av = ac2.get(ig, 0.0) * wgt
                    if sname not in tree:
                        tree[sname] = {"t": 0.0, "a": 0.0, "sp": {}}
                    tree[sname]["t"] = tree[sname]["t"] + tv
                    tree[sname]["a"] = tree[sname]["a"] + av
                    if spn not in tree[sname]["sp"]:
                        tree[sname]["sp"][spn] = {"t": 0.0, "a": 0.0, "it": {}}
                    tree[sname]["sp"][spn]["t"] = tree[sname]["sp"][spn]["t"] + tv
                    tree[sname]["sp"][spn]["a"] = tree[sname]["sp"][spn]["a"] + av
                    inm = ig
                    if inm[0:6] == "group-":
                        inm = inm[6:]
                    tree[sname]["sp"][spn]["it"][inm] = {"t": tv, "a": av}
            tt2 = 0.0
            aa2 = 0.0
            acc3 = 0.0
            ns3 = 0
            dd2 = []
            for sname in tree:
                if tree[sname]["t"] <= 0:
                    continue
                sv = 100.0 * tree[sname]["a"] / tree[sname]["t"] / pace
                cs = sv
                if cs > 120:
                    cs = 120.0
                acc3 = acc3 + cs
                ns3 = ns3 + 1
                tt2 = tt2 + tree[sname]["t"]
                aa2 = aa2 + tree[sname]["a"]
                pl2 = []
                for spn in tree[sname]["sp"]:
                    dsp = tree[sname]["sp"][spn]
                    pv2 = 0.0
                    if dsp["t"] > 0:
                        pv2 = 100.0 * dsp["a"] / dsp["t"] / pace
                    il2 = []
                    for inm in dsp["it"]:
                        di = dsp["it"][inm]
                        iv2 = 0.0
                        if di["t"] > 0:
                            iv2 = 100.0 * di["a"] / di["t"] / pace
                            if iv2 > 999:
                                iv2 = 999.0
                        il2.append({"item": inm, "tgt": round(di["t"], 0), "ach": round(di["a"], 0), "pct": round(iv2, 1)})
                    il2.sort(key=lambda z: z["pct"])
                    pl2.append({"sp": spn, "tgt": round(dsp["t"], 0), "ach": round(dsp["a"], 0), "pct": round(pv2, 1), "items": il2})
                pl2.sort(key=lambda z: z["pct"])
                dd2.append({"sp": sname, "tgt": round(tree[sname]["t"], 0), "ach": round(tree[sname]["a"], 0), "pct": round(sv, 1), "agents": pl2})
            dd2.sort(key=lambda z: z["pct"])
            m1 = None
            if tt2 > 0:
                m1 = round(100.0 * aa2 / tt2 / pace, 1)
            m5 = None
            if ns3:
                m5 = round(acc3 / ns3, 1)
            m6 = None
            if mr["emp"] in evmap:
                m6 = round(evmap[mr["emp"]], 1)
            arn2 = (mr["wh"] or "(غير محدد)")
            if arn2[-4:] == " - S":
                arn2 = arn2[0:-4]
            arn2 = arn2.replace("موظفين ", "").strip()
            vv2 = [m1, m5, m6]
            nu2 = 0.0
            de2 = 0.0
            ct2 = 0
            jj = 0
            for v in vv2:
                if v is not None:
                    cp2 = v
                    if cp2 > 120:
                        cp2 = 120.0
                    nu2 = nu2 + cp2 * WM[jj]
                    de2 = de2 + WM[jj]
                    ct2 = ct2 + 1
                jj = jj + 1
            cm2 = None
            if de2 > 0 and ct2 >= 2:
                cm2 = round(nu2 / de2, 1)
            mout.append({"emp": mr["emp"], "name": mr["nm"], "area": arn2, "email": "", "med": 1, "customers": 0, "p1": m1, "p2": None, "p3": None, "p4": None, "p5": m5, "p6": m6, "comp": cm2, "npillar": ct2, "target": round(tt2, 0), "achieved": round(aa2, 0), "focus_detail": dd2, "assignments": len(asg)})
        out = mout

    if groupby == "area":
        gm = {}
        for x in out:
            a = x["area"]
            if a not in gm:
                gm[a] = {"n": 0, "t": 0.0, "ac": 0.0, "pd": 0.0, "cs": 0.0, "cc": 0.0, "nc": 0, "blk": 0, "tch": 0, "sp": {}, "s6": 0.0, "n6": 0}
            g = gm[a]
            g["n"] = g["n"] + 1
            g["t"] = g["t"] + x["zt"]
            g["ac"] = g["ac"] + x["za"]
            g["pd"] = g["pd"] + x["zpd"]
            g["cs"] = g["cs"] + x["zcs"]
            g["cc"] = g["cc"] + x["zcc"]
            g["nc"] = g["nc"] + x["znc"]
            g["blk"] = g["blk"] + x["zblk"]
            g["tch"] = g["tch"] + x["ztch"]
            if x["zp6"] is not None:
                g["s6"] = g["s6"] + x["zp6"]
                g["n6"] = g["n6"] + 1
            for f in x["zfd"]:
                k = f["sp"]
                if k not in g["sp"]:
                    g["sp"][k] = {"t": 0.0, "a": 0.0, "it": {}}
                g["sp"][k]["t"] = g["sp"][k]["t"] + f["tgt"]
                g["sp"][k]["a"] = g["sp"][k]["a"] + f["ach"]
                for it in (f.get("items") or []):
                    ik = it["item"]
                    if ik not in g["sp"][k]["it"]:
                        g["sp"][k]["it"][ik] = {"t": 0.0, "a": 0.0}
                    g["sp"][k]["it"][ik]["t"] = g["sp"][k]["it"][ik]["t"] + it["tgt"]
                    g["sp"][k]["it"][ik]["a"] = g["sp"][k]["it"][ik]["a"] + it["ach"]
        aout = []
        for a in gm:
            g = gm[a]
            q1 = None
            if g["t"] > 0:
                q1 = round(100.0 * g["ac"] / g["t"] / pace, 1)
            dn = (PF * g["pd"] / 12.0 * months) + (CF * g["cs"])
            q2 = None
            if dn > 0:
                q2 = round(100.0 * g["cc"] / dn, 1)
            q3 = None
            q4 = None
            if g["nc"] > 0:
                q3 = round(100.0 - (100.0 * g["blk"] / g["nc"]), 1)
                q4 = round(100.0 * g["tch"] / g["nc"], 1)
            dd = []
            acc2 = 0.0
            ns2 = 0
            for k in g["sp"]:
                if g["sp"][k]["t"] > 0:
                    v2 = 100.0 * g["sp"][k]["a"] / g["sp"][k]["t"] / pace
                    if v2 > 120:
                        v2 = 120.0
                    acc2 = acc2 + v2
                    ns2 = ns2 + 1
                    ir = []
                    for ik in g["sp"][k]["it"]:
                        tt2 = g["sp"][k]["it"][ik]["t"]
                        aa2 = g["sp"][k]["it"][ik]["a"]
                        pv = 0.0
                        if tt2 > 0:
                            pv = 100.0 * aa2 / tt2 / pace
                            if pv > 999:
