                        ir.append({"item": ik, "tgt": round(tt2, 0), "ach": round(aa2, 0), "pct": round(pv, 1)})
                    ir.sort(key=lambda z: z["pct"])
                    dd.append({"sp": k, "tgt": round(g["sp"][k]["t"], 0), "ach": round(g["sp"][k]["a"], 0), "pct": round(v2, 1), "items": ir})
            dd.sort(key=lambda z: z["pct"])
            q5 = None
            if ns2:
