            q6 = None
            if g["n6"] > 0:
                q6 = round(g["s6"] / g["n6"], 1)
            vv = [q1, q2, q3, q4, q5, q6]
            nu = 0.0
            de = 0.0
            ct = 0
            ii = 0
            for v in vv:
                if v is not None:
                    cp = v
                    if cp > 120:
                        cp = 120.0
                    nu = nu + cp * W[ii]
                    de = de + W[ii]
                    ct = ct + 1
                ii = ii + 1
            cmp2 = None
            if de > 0 and ct >= 4:
                cmp2 = round(nu / de, 1)
            aout.append({"emp": a, "name": a, "area": a, "email": "", "med": 0, "customers": g["nc"], "p1": q1, "p2": q2, "p3": q3, "p4": q4, "p5": q5, "p6": q6, "comp": cmp2, "npillar": ct, "target": round(g["t"], 0), "achieved": round(g["ac"], 0), "focus_detail": dd, "agents": g["n"]})
