            amount = frappe.utils.flt(r.get("amount") or 0)
            if r.get("docstatus") != 2:
                if action == "ايداع":
                    total_deposit += amount
                elif action == "سحب":
                    total_draw += amount

        # Resolve customer display names
        cust_ids = []
        for row in rows:
            if row.get("customer") and row.get("customer") not in cust_ids:
                cust_ids.append(row.get("customer"))
        cname = {}
        if cust_ids:
            for c in frappe.get_all("Customer", filters=[["name", "in", cust_ids]], fields=["name", "customer_name"]):
                cname[c.name] = c.customer_name or c.name
        for row in rows:
            row["customer_display"] = cname.get(row.get("customer"), row.get("customer") or "")

        # Group PAGE rows by date
        grouped = {}
        for row in rows:
            date_key = str(frappe.utils.getdate(row.get("creation")))
            grouped.setdefault(date_key, []).append(row)

        frappe.response["message"] = {
            "ledger": grouped,
            "totals": {"deposit": total_deposit, "draw": total_draw},
            "meta": {
                "limit": limit,
                "start": start,
                "has_more": has_more,
                "user": user,
                "rows_returned": len(rows)
            }
        }

