else:
    locations = frappe.get_all("Cost Center",
                               filters={"is_group": 0},
                               fields=["name", "cost_center_name"],
                               limit_page_length=2000)

if customer:
    regions = frappe.db.sql("""
        SELECT DISTINCT
            CONCAT(a.city, ' - ', a.county) as name,
            CONCAT(a.city, ' - ', a.county) as region_name
        FROM `tabAddress` a
        JOIN `tabDynamic Link` dl ON dl.parent = a.name
        WHERE dl.link_doctype = 'Customer'
        AND dl.link_name = %s
        AND a.county IS NOT NULL AND a.county != ''
        AND a.city IS NOT NULL AND a.city != ''
        ORDER BY a.county asc
    """, customer, as_dict=True)
elif emp:
    emp_user_email_r = frappe.db.get_value("Employee", emp, "user_id")
    if emp_user_email_r:
        cust_ids_r = frappe.get_all("Customer",
            filters={"account_manager": emp_user_email_r},
            pluck="name", limit_page_length=5000)
        if cust_ids_r:
            regions = frappe.db.sql("""
                SELECT DISTINCT
                    CONCAT(a.city, ' - ', a.county) as name,
                    CONCAT(a.city, ' - ', a.county) as region_name
                FROM `tabAddress` a
                JOIN `tabDynamic Link` dl ON dl.parent = a.name
                WHERE dl.link_doctype = 'Customer'
                AND dl.link_name IN %s
                AND a.county IS NOT NULL AND a.county != ''
                AND a.city IS NOT NULL AND a.city != ''
                ORDER BY a.county asc
            """, [cust_ids_r], as_dict=True)
        else:
            regions = []
    else:
        regions = []
else:
    regions = frappe.db.sql("""
        SELECT DISTINCT
            CONCAT(city, ' - ', county) as name,
            CONCAT(city, ' - ', county) as region_name
        FROM `tabAddress`
        WHERE county IS NOT NULL AND county != ''
        AND city IS NOT NULL AND city != ''
