# warehouse_undo_picking (Server Script - API) ✅ safe_exec compatible (NO import)
# Input: so_name
# Revert: PICKING -> NEW (and clear flags)
# Returns: frappe.response["message"] = {"ok": True/False, ...}

so_name = (frappe.form_dict.get("so_name") or "").strip()

# Basic auth check (safe)
if frappe.session.user == "Guest":
    frappe.response["message"] = {"ok": False, "error": "Guest not allowed"}
    raise SystemExit

if not so_name:
    frappe.response["message"] = {"ok": False, "error": "Missing so_name"}
    raise SystemExit

# Ensure Sales Order exists
if not frappe.db.exists("Sales Order", so_name):
    frappe.response["message"] = {"ok": False, "error": "Sales Order not found: " + so_name}
    raise SystemExit

try:
    meta = frappe.get_meta("Sales Order")

    def safe_set(fieldname, value):
        # only set if field exists
        if meta and meta.has_field(fieldname):
            frappe.db.set_value("Sales Order", so_name, fieldname, value, update_modified=True)

    # ✅ revert status to NEW
    safe_set("custom_warehouse_status", "NEW")
    safe_set("custom_log_1", 0)   # ✅ clear printed flag on Sales Order
    safe_set("custom_log_2", 0)
    safe_set("custom_log_3", 0)
    safe_set("custom_log_4", 0)

    # ✅ Also clear printed flag on linked Delivery Note (if any)
    dn_name = frappe.db.get_value("Delivery Note Item", {"against_sales_order": so_name}, "parent")
    if dn_name and frappe.db.exists("Delivery Note", dn_name):
        dn_meta = frappe.get_meta("Delivery Note")
        if dn_meta and dn_meta.has_field("custom_log_1"):
            frappe.db.set_value("Delivery Note", dn_name, "custom_log_1", 0, update_modified=True)

    frappe.db.commit()
    frappe.response["message"] = {"ok": True, "so_name": so_name}

except Exception as e:
    frappe.db.rollback()
    # Don't use frappe.get_traceback (blocked). Just send error string.
    frappe.response["message"] = {"ok": False, "error": str(e)}

