# API Name: leave_approval_get
# Purpose:
# - Show only Leave Applications where the current user has allowed workflow actions
# - Exact states per your workflow:
#   Supervisor bucket: "Manager Approval"
#   HR bucket:        "HR Approval"
# IMPORTANT:
# - Your workflow keeps these states at docstatus=0 (Draft), so we MUST NOT filter docstatus=1.

def norm_str(s):
    try:
        return (s or "").strip()
    except Exception:
        return ""

if frappe.session.user == "Guest":
    frappe.throw("Not permitted", frappe.PermissionError)

# limit
limit = 80
try:
    limit = int(frappe.form_dict.get("limit") or 80)
except Exception:
    limit = 80
if limit < 1:
    limit = 1
if limit > 200:
    limit = 200

wait_states = ["Manager Approval", "HR Approval"]

# Pull candidates in waiting states (draft/submitted), then filter by real workflow transitions per user
rows = frappe.get_all(
    "Leave Application",
    filters={
        "docstatus": ["<", 2],               # include Draft (0) and Submitted (1), exclude Cancelled (2)
        "workflow_state": ["in", wait_states]
    },
    fields=[
        "name", "employee", "employee_name",
        "leave_type", "from_date", "to_date",
        "half_day", "workflow_state", "status",
        "description", "modified", "docstatus"
    ],
    order_by="modified desc",
    limit_page_length=300
)

supervisor_items = []
hr_items = []

for r in rows:
    try:
        doc = frappe.get_doc("Leave Application", r["name"])

        # Filter strictly by what the current user can do
        transitions = frappe.model.workflow.get_transitions(doc, frappe.session.user) or []
        if not transitions:
            continue

        actions = []
        for t in transitions:
            act = t.get("action")
            if act and act not in actions:
                actions.append(act)

        if not actions:
            continue

        item = {
            "name": doc.name,
            "employee": doc.get("employee"),
            "employee_name": doc.get("employee_name"),
            "leave_type": doc.get("leave_type"),
            "from_date": str(doc.get("from_date") or ""),
            "to_date": str(doc.get("to_date") or ""),
            "half_day": 1 if doc.get("half_day") else 0,
            "workflow_state": doc.get("workflow_state") or "",
            "status": doc.get("status") or "",
            "description": (doc.get("description") or ""),
            "docstatus": int(doc.docstatus or 0),
            "actions": actions
        }

        if item["workflow_state"] == "Manager Approval":
            supervisor_items.append(item)
        elif item["workflow_state"] == "HR Approval":
            hr_items.append(item)

        if (len(supervisor_items) + len(hr_items)) >= limit:
            break

    except Exception:
        continue

frappe.response["message"] = {
    "user": frappe.session.user,
    "supervisor": supervisor_items,
    "hr": hr_items
}

# API Name: leave_approval_action
# Purpose:
# - Apply a workflow action to a Leave Application
# - Validate the current user is allowed to do that action (workflow transitions)

def norm_str(s):
    try:
        return (s or "").strip()
    except Exception:
        return ""

if frappe.session.user == "Guest":
    frappe.throw("Not permitted", frappe.PermissionError)

docname = norm_str(frappe.form_dict.get("docname"))
action = norm_str(frappe.form_dict.get("action"))

if not docname or not action:
    frappe.throw("Missing docname/action")

doc = frappe.get_doc("Leave Application", docname)

# Validate allowed actions for current user
transitions = frappe.model.workflow.get_transitions(doc, frappe.session.user) or []
allowed_actions = []
for t in transitions:
    if t.get("action"):
        allowed_actions.append(t.get("action"))

if action not in allowed_actions:
    frappe.throw("Action not permitted for this user")

# Apply workflow action (this saves the doc)
frappe.model.workflow.apply_workflow(doc, action)

# Reload to return updated state
doc = frappe.get_doc("Leave Application", docname)

frappe.response["message"] = {
    "ok": True,
    "docname": doc.name,
    "new_workflow_state": doc.get("workflow_state") or "",
    "new_status": doc.get("status") or ""
}

