                "max_receipt_number": [">=", receipt_no_int]
            },
            fields=["name", "min_receipt_number", "max_receipt_number", "posting_date"],
            limit_page_length=1
        )
        if rows:
            return rows[0]
    rows = frappe.get_all(
        "LMT Receipt Counter",
        filters={
            "docstatus": 1,
            "assigned_user": user,
