    else:
        nm = (frappe.form_dict.get('area_name') or '').strip()
        at = (frappe.form_dict.get('area_type') or '').strip()
        pa = (frappe.form_dict.get('parent') or '').strip()

        if not nm:
            frappe.response['message'] = {'status': 'error', 'message': 'الاسم مطلوب'}
        elif at not in ('منطقة', 'بلدية'):
            frappe.response['message'] = {'status': 'error', 'message': 'نوع غير صحيح'}
        elif frappe.db.exists('LMT Area', nm):
            ex = frappe.db.get_value('LMT Area', nm, ['area_type', 'parent_area'], as_dict=True)
            frappe.response['message'] = {'status': 'error',
                'message': 'الاسم موجود مسبقاً: ' + nm + ' (' + (ex['area_type'] or '') + ')'}
        elif at == 'بلدية' and not pa:
            frappe.response['message'] = {'status': 'error', 'message': 'اختر المنطقة أولاً'}
        elif at == 'بلدية' and not frappe.db.sql("""
                select 1 from `tabLMT Area`
                where name=%s and area_type='منطقة' limit 1
            """, (pa,)):
            frappe.response['message'] = {'status': 'error', 'message': 'المنطقة غير صحيحة: ' + pa}
        else:
            doc = frappe.new_doc('LMT Area')
            doc.area_name = nm
            doc.area_type = at
            doc.is_group = 1
            doc.is_active = 1
            if at == 'بلدية':
                doc.parent_area = pa
            doc.insert(ignore_permissions=True)
            frappe.response['message'] = {'status': 'ok', 'name': nm, 'area_type': at, 'parent': pa}

elif action == 'rename_area':
    if not can_edit:
        frappe.response['message'] = {'status': 'error', 'message': 'غير مصرح لك بالتعديل'}
    else:
        old = (frappe.form_dict.get('old_name') or '').strip()
        new = (frappe.form_dict.get('new_name') or '').strip()

        if not old or not new:
            frappe.response['message'] = {'status': 'error', 'message': 'الاسم القديم والجديد مطلوبان'}
        elif old == new:
            frappe.response['message'] = {'status': 'error', 'message': 'لا يوجد تغيير'}
        elif not frappe.db.exists('LMT Area', old):
            frappe.response['message'] = {'status': 'error', 'message': 'غير موجود: ' + old}
        elif frappe.db.exists('LMT Area', new):
            frappe.response['message'] = {'status': 'error', 'message': 'الاسم الجديد موجود مسبقاً: ' + new}
        else:
            at = frappe.db.get_value('LMT Area', old, 'area_type')
            fld = 'state' if at == 'منطقة' else 'county'
            hits = frappe.get_all('Address', filters={fld: old}, fields=['name'], limit_page_length=0)
            frappe.rename_doc('LMT Area', old, new, force=True)
            n_addr = 0
            for hh in hits:
                frappe.db.set_value('Address', hh['name'], fld, new, update_modified=False)
                n_addr = n_addr + 1
            frappe.response['message'] = {'status': 'ok', 'old': old, 'new': new,
                                          'area_type': at, 'addresses': n_addr}

elif action == 'delete_area':
    if not can_edit:
        frappe.response['message'] = {'status': 'error', 'message': 'غير مصرح لك بالحذف'}
    else:
        nm = (frappe.form_dict.get('area_name') or '').strip()
        mode = (frappe.form_dict.get('mode') or 'delete').strip()

        if not nm or not frappe.db.exists('LMT Area', nm):
            frappe.response['message'] = {'status': 'error', 'message': 'غير موجود: ' + nm}
        else:
            at = frappe.db.get_value('LMT Area', nm, 'area_type')
            n_kids = frappe.db.sql('select count(*) from `tabLMT Area` where parent_area=%s', (nm,))[0][0]
            if at == 'منطقة':
                n_use = frappe.db.sql('select count(*) from `tabAddress` where state=%s', (nm,))[0][0]
            else:
                n_use = frappe.db.sql('select count(*) from `tabAddress` where county=%s', (nm,))[0][0]

            if mode == 'deactivate':
                frappe.db.set_value('LMT Area', nm, 'is_active', 0)
                frappe.response['message'] = {'status': 'ok', 'mode': 'deactivate', 'name': nm}
            elif n_kids:
                frappe.response['message'] = {'status': 'error',
                    'message': 'لا يمكن الحذف: يتبعها ' + str(n_kids) + ' بلدية'}
            elif n_use:
                frappe.response['message'] = {'status': 'error',
                    'message': 'لا يمكن الحذف: مستخدمة في ' + str(n_use) + ' عنوان — استخدم التعطيل بدلاً من الحذف',
                    'can_deactivate': 1, 'uses': n_use}
            else:
                frappe.delete_doc('LMT Area', nm, ignore_permissions=True)
                frappe.response['message'] = {'status': 'ok', 'mode': 'delete', 'name': nm}

else:
    frappe.response['message'] = {'status': 'error', 'message': 'unknown action'}

