try:
    if doc.amended_from or doc.get("is_return"):
        if not doc.custom_my_generated_id:
            linked_si = None
            if doc.get("is_return") and doc.items:
                for item in doc.items:
                    if item.get("against_sales_invoice"):
                        linked_si = item.against_sales_invoice
                        break

            if doc.amended_from and not doc.get("is_return"):
                base_fb = doc.amended_from
                n = 0
                fallback = base_fb
                while frappe.db.exists("Delivery Note", fallback):
                    n = n + 1
                    fallback = base_fb + "-" + str(n)
                doc.custom_my_generated_id = fallback
                doc.name = fallback

            if linked_si and "INV-" in linked_si:
                fallback = linked_si.replace("INV-", "DN-") + "-R"
                base_fb = fallback
                n = 1
                while frappe.db.exists("Delivery Note", fallback):
                    n = n + 1
                    fallback = base_fb + "-" + str(n)
                doc.custom_my_generated_id = fallback
                doc.name = fallback

        if not doc.custom_my_generated_id:
            user = frappe.get_doc("User", doc.owner)
            initials = user.custom_txt_4 or "XX"

            now_str = str(frappe.utils.now())
            yymmdd = now_str[2:4] + now_str[5:7] + now_str[8:10]

            current_val = user.custom_invoice_counter or 0
            new_val = current_val + 1
            user.db_set("custom_invoice_counter", new_val)

            padded_counter = str(10000 + new_val)[1:]

            if doc.get("is_return"):
                fallback = "DN-" + initials + "-" + yymmdd + "-" + padded_counter + "-R"
            else:
                fallback = "DN-" + initials + "-" + yymmdd + "-" + padded_counter

            base_fb = fallback
            n = 1
            while frappe.db.exists("Delivery Note", fallback):
                n = n + 1
                fallback = base_fb + "-" + str(n)

            doc.custom_my_generated_id = fallback
            doc.name = fallback
    else:
        linked_order = None
        if doc.items:
            for item in doc.items:
                if item.against_sales_order:
                    linked_order = item.against_sales_order
                    break

        new_name = ""

        if linked_order and "SAL-" in linked_order:
            new_name = linked_order.replace("SAL-", "DN-")
        else:
            user = frappe.get_doc("User", doc.owner)
            initials = user.custom_txt_4 or "XX"

            now_str = str(frappe.utils.now())
            yymmdd = now_str[2:4] + now_str[5:7] + now_str[8:10]

            current_val = user.custom_invoice_counter or 0
            new_val = current_val + 1
            user.db_set("custom_invoice_counter", new_val)

            padded_counter = str(10000 + new_val)[1:]
            new_name = "DN-" + initials + "-" + yymmdd + "-" + padded_counter

        if new_name:
            base_name = new_name
            suffix = 1
            while frappe.db.exists("Delivery Note", new_name):
                suffix = suffix + 1
                new_name = base_name + "-" + str(suffix)

            doc.custom_my_generated_id = new_name
            doc.name = new_name

    if not doc.naming_series:
        doc.naming_series = "MAT-DN-.YYYY.-"

except Exception as e:
    frappe.log_error("Delivery Note Naming Error", str(e))
